<?php defined('BX_DOL') or die('hack attempt');
require_once __DIR__.'/NwStyledPostsCard.php';
class NwStyledPostsComposer
{
    public static function render(array $values, array $catalog, string $assetBase, string $backgroundUrl = '', array $photos = []): string
    {
        $s=NwStyledPostsStyle::forEditor($values,$catalog);
        $e=[NwStyledPostsStyle::class,'escape'];
        $options='';
        foreach($catalog['fonts'] as $id=>$font) if($font['enabled']) $options.='<option value="'.$e($id).'"'.($s['font_name']===$id?' selected':'').'>'.$e($font['label']).'</option>';
        $swatches='';$motionSwatches='';
        foreach($catalog['backgrounds'] as $id=>$bg) {
            if(!$bg['enabled']) continue;
            $css='background-color:'.($id==='solid'?$s['background_color']:'#6554C0').';background-image:'.$bg['css'];
            if(!empty($bg['file'])) $css.=';background-image:url('.$assetBase.'images/backgrounds/'.$bg['file'].')';
            if (($bg['kind']??'')==='motion') $css.=';background-image:url('.$assetBase.'motion/'.$bg['poster'].')';
            $button='<button type="button" class="nwsp-swatch" data-background="'.$e($id).'" aria-label="'.$e($bg['label']).'" aria-pressed="'.($id===$s['background']?'true':'false').'" title="'.$e($bg['label']).'" style="'.$e($css).'"></button>';
            if (($bg['kind']??'')==='motion') $motionSwatches.='<button type="button" class="nwsp-motion-choice" data-background="'.$e($id).'" aria-label="'.$e($bg['label']).'" aria-pressed="'.($id===$s['background']?'true':'false').'"><span class="nwsp-motion-thumb" style="'.$e($css).'" aria-hidden="true"><span>▶</span></span><span class="nwsp-motion-label">'.$e($bg['label']).'</span></button>';else $swatches.=$button;
        }
        $align='';foreach(['left'=>'Left','center'=>'Center','right'=>'Right'] as $id=>$label) $align.='<button type="button" data-align="'.$id.'" aria-label="Align '.$label.'" aria-pressed="'.($s['text_align']===$id?'true':'false').'">'.$label.'</button>';
        $available=count(array_filter($catalog['fonts'],fn($f)=>$f['enabled']))>0 && count(array_filter($catalog['backgrounds'],fn($b)=>$b['enabled']))>0;
        $json=json_encode(['available'=>$available,'catalog'=>$catalog,'assetBase'=>$assetBase,'values'=>$s,'backgroundUrl'=>$backgroundUrl,'photos'=>$photos],JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_UNESCAPED_UNICODE);
        $picker='';
        $motionControls='<details class="nwsp-motion-choices"'.(($catalog['backgrounds'][$s['background']]['kind']??'')==='motion'?' open':'').'><summary><span class="nwsp-motion-icon" aria-hidden="true">▶</span><span class="nwsp-motion-heading">Motion backgrounds<span class="nwsp-motion-subtitle">3–5 second loops · Choose a moving backdrop</span></span><span class="nwsp-motion-chevron" aria-hidden="true">⌄</span></summary><p class="nwsp-help">Original illustrated loops · silent and made for your words.</p><div class="nwsp-motion-grid" role="group" aria-label="Motion backgrounds">'.$motionSwatches.'</div>'.(!empty($photos['motionUploads'])?'<button type="button" data-upload-motion>Upload video or GIF</button><p class="nwsp-help">MP4, WebM, MOV or animated GIF · 3–5 seconds · up to 8 MiB · 1280 pixels per side. Played without sound.</p>':'<p class="nwsp-help">Choose a built-in loop. Motion uploads are unavailable on this site.</p>').'</details>';
        if (($photos['enabled']??true)) $picker='<div class="nwsp-photo-actions"><button type="button" data-choose-photos>Choose from my photos</button><button type="button" data-upload-photo>Upload photo</button><input type="hidden" name="background_photo" value="'.(int)($photos['selected']??0).'"></div><p class="nwsp-help">Your selected photo is copied as a background and shared with your post’s audience.</p><dialog class="nwsp-photo-dialog" aria-label="Choose from my photos"><div class="nwsp-photo-heading"><strong>Choose from my photos</strong><button type="button" data-close-photos aria-label="Close photo picker">Close</button></div><p data-photo-status role="status" aria-live="polite"></p><div class="nwsp-photo-grid"></div><button type="button" data-more-photos hidden>Load more photos</button></dialog>';
        $extras='<details class="nwsp-readability"><summary>Text backdrop &amp; direction</summary><div class="nwsp-adjust-grid"><label>Text backdrop<select data-control="text_backdrop"><option value="none"'.($s['text_backdrop']==='none'?' selected':'').'>None</option><option value="box"'.($s['text_backdrop']==='box'?' selected':'').'>Box</option></select></label><label>Backdrop color<input type="color" data-control="backdrop_color" value="'.$s['backdrop_color'].'"></label>';
        foreach (['backdrop_opacity'=>['Opacity',0,100,'%'],'backdrop_padding'=>['Padding',0,32,'px']] as $key=>[$label,$min,$max,$unit]) $extras.='<label>'.$label.' <output data-output="'.$key.'">'.$s[$key].$unit.'</output><input type="range" data-control="'.$key.'" min="'.$min.'" max="'.$max.'" value="'.$s[$key].'" data-unit="'.$unit.'"></label>';
        $extras.='<label>Text direction<select data-control="text_direction">';
        foreach (['auto'=>'Automatic','ltr'=>'Left to right','rtl'=>'Right to left'] as $key=>$label) $extras.='<option value="'.$key.'"'.($s['text_direction']===$key?' selected':'').'>'.$label.'</option>';
        $extras.='</select></label></div></details>';
        $framing='<details class="nwsp-image-adjust" hidden><summary>Adjust image</summary><div class="nwsp-adjust-grid">';
        foreach (['image_x'=>['Horizontal position',0,100],'image_y'=>['Vertical position',0,100],'image_zoom'=>['Image zoom',100,250]] as $key=>[$label,$min,$max]) $framing.='<label>'.$label.' <output data-output="'.$key.'">'.$s[$key].'%</output><input type="range" data-control="'.$key.'" min="'.$min.'" max="'.$max.'" value="'.$s[$key].'" data-unit="%"></label>';
        $framing.='</div><button type="button" data-reset-image>Reset image</button><p class="nwsp-help">Zoom and position the image to crop it. Your original stays unchanged.</p></details>';
        $faces='';foreach($catalog['fonts'] as $id=>$font) if (!empty($font['custom']) && defined('BX_DOL_URL_ROOT')) $faces.='@font-face{font-family:NWCustom_'.substr($id,7).';src:url("'.$e(BX_DOL_URL_ROOT.'modules/?r=styled_posts/font/'.substr($id,7)).'") format("woff2");font-display:swap}';
        return ($faces?'<style>'.$faces.'</style>':'').'<section class="nwsp-composer" aria-label="Style your post"><div class="nwsp-toolbar"><label>Font<select data-control="font_name">'.$options.'</select></label><label>Size <output data-size-label>'.$s['font_size'].'</output><input type="range" data-control="font_size" min="18" max="96" step="1" value="'.$s['font_size'].'"></label><label>Text color<input type="color" data-control="text_color" value="'.$s['text_color'].'"></label><label>Background color<input type="color" data-control="background_color" value="'.$s['background_color'].'"></label></div><div class="nwsp-align" role="group" aria-label="Text alignment">'.$align.'</div>'.$extras.'<div class="nwsp-background-heading"><strong>Choose your backdrop</strong><span>Colors · gradients · patterns · pictures</span></div><div class="nwsp-swatches" role="group" aria-label="Backgrounds">'.$swatches.'</div>'.$motionControls.$picker.'<p class="nwsp-help">Find background photos: <a href="https://www.pexels.com/" target="_blank" rel="noopener noreferrer">Pexels</a> (<a href="https://www.pexels.com/license/" target="_blank" rel="noopener noreferrer">license</a>) · <a href="https://unsplash.com/" target="_blank" rel="noopener noreferrer">Unsplash</a> (<a href="https://unsplash.com/license" target="_blank" rel="noopener noreferrer">license</a>). Download a free image there, then upload it here. Check the image’s usage terms.</p>'.$framing.'<p class="nwsp-help">Drag the text in the preview to move it. Or focus the text and use the arrow keys; hold Shift for larger steps.</p><button type="button" data-reset-position>Reset position</button><div class="nwsp-preview">'.NwStyledPostsCard::render($values,$catalog,$assetBase,$backgroundUrl,$photos['motion']??[]).'</div><div class="nwsp-preview-footer"><span>LIVE PREVIEW</span><span data-count>0 / 500</span></div><p class="nwsp-feedback" data-feedback role="status" aria-live="polite"></p><p class="nwsp-help">Your words stay editable. Choose your audience below before posting.</p><script type="application/json" class="nwsp-config">'.$json.'</script></section>';
    }
}
